$$;


--
-- Name: cleanup_old_sessions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_sessions(max_age_hours integer DEFAULT 24) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- First, handle sessions that are expired due to inactivity
  UPDATE active_sessions 
  SET status = 'expired'
  WHERE status = 'active' 
    AND last_active < NOW() - (max_age_hours || ' hours')::interval;

  -- Delete old ended/expired sessions after 24 hours
  DELETE FROM active_sessions 
  WHERE (status = 'ended' OR status = 'expired')
    AND last_active < NOW() - '24 hours'::interval;

  -- Log the cleanup count (optional)
  RAISE NOTICE 'Cleaned up sessions older than % hours', max_age_hours;
END;
$$;


--
-- Name: get_effective_pay_rate(character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_pay_rate(p_employee_id character varying, p_job_id character varying, p_pay_code_id character varying, p_year integer, p_month integer) RETURNS TABLE(rate_biasa numeric, rate_ahad numeric, rate_umum numeric)
    LANGUAGE sql STABLE
    AS $$
  WITH emp AS (
    SELECT s.rate_biasa, s.rate_ahad, s.rate_umum FROM pay_rate_schedules s
    WHERE s.scope = 'employee' AND s.employee_id = p_employee_id AND s.pay_code_id = p_pay_code_id
      AND (s.effective_year * 12 + s.effective_month) <= (p_year * 12 + p_month)
    ORDER BY s.effective_year DESC, s.effective_month DESC LIMIT 1
  ),
  job AS (
    SELECT s.rate_biasa, s.rate_ahad, s.rate_umum FROM pay_rate_schedules s
    WHERE s.scope = 'job' AND s.job_id = p_job_id AND s.pay_code_id = p_pay_code_id
      AND (s.effective_year * 12 + s.effective_month) <= (p_year * 12 + p_month)
    ORDER BY s.effective_year DESC, s.effective_month DESC LIMIT 1
  ),
  pc AS (
    SELECT s.rate_biasa, s.rate_ahad, s.rate_umum FROM pay_rate_schedules s
    WHERE s.scope = 'pay_code' AND s.pay_code_id = p_pay_code_id
      AND (s.effective_year * 12 + s.effective_month) <= (p_year * 12 + p_month)
    ORDER BY s.effective_year DESC, s.effective_month DESC LIMIT 1
  )
  SELECT
    COALESCE((SELECT e.rate_biasa FROM emp e), epc.override_rate_biasa,
             (SELECT j.rate_biasa FROM job j), jpc.override_rate_biasa,
             (SELECT p.rate_biasa FROM pc p), pcd.rate_biasa),
    COALESCE((SELECT e.rate_ahad FROM emp e), epc.override_rate_ahad,
             (SELECT j.rate_ahad FROM job j), jpc.override_rate_ahad,
             (SELECT p.rate_ahad FROM pc p), pcd.rate_ahad),
    COALESCE((SELECT e.rate_umum FROM emp e), epc.override_rate_umum,
             (SELECT j.rate_umum FROM job j), jpc.override_rate_umum,
             (SELECT p.rate_umum FROM pc p), pcd.rate_umum)
  FROM pay_codes pcd
  LEFT JOIN employee_pay_codes epc ON epc.employee_id = p_employee_id AND epc.pay_code_id = p_pay_code_id
  LEFT JOIN job_pay_codes jpc ON jpc.job_id = p_job_id AND jpc.pay_code_id = p_pay_code_id
  WHERE pcd.id = p_pay_code_id;
$$;


