);


--
-- Name: account_codes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_codes (
    id integer NOT NULL,
    code character varying(50) NOT NULL,
    description character varying(255) NOT NULL,
    ledger_type character varying(10),
    parent_code character varying(50),
    level integer DEFAULT 1,
    sort_order integer DEFAULT 0,
    is_active boolean DEFAULT true,
    is_system boolean DEFAULT false,
    notes text,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    created_by character varying(50),
    updated_by character varying(50),
    fs_note character varying(10)
);


--
-- Name: COLUMN account_codes.is_system; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_codes.is_system IS 'System accounts that should not be deleted by users';


--
-- Name: COLUMN account_codes.fs_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account_codes.fs_note IS 'Financial statement note reference (e.g., 1, 3-1, 14-2)';


--
-- Name: account_codes_hierarchy; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.account_codes_hierarchy AS
 WITH RECURSIVE account_tree AS (
         SELECT account_codes.id,
            account_codes.code,
            account_codes.description,
            account_codes.ledger_type,
            account_codes.parent_code,
            account_codes.level,
            account_codes.sort_order,
            account_codes.is_active,
            account_codes.is_system,
            (account_codes.code)::text AS path,
            ARRAY[(account_codes.code)::text] AS path_array,
            1 AS depth
           FROM public.account_codes
          WHERE (account_codes.parent_code IS NULL)
        UNION ALL
         SELECT ac.id,
            ac.code,
            ac.description,
            ac.ledger_type,
            ac.parent_code,
            ac.level,
            ac.sort_order,
            ac.is_active,
            ac.is_system,
            ((at.path || ' > '::text) || (ac.code)::text) AS path,
            (at.path_array || (ac.code)::text) AS path_array,
            (at.depth + 1) AS depth
           FROM (public.account_codes ac
             JOIN account_tree at ON (((ac.parent_code)::text = (at.code)::text)))
        )
 SELECT id,
    code,
    description,
    ledger_type,
    parent_code,
    level,
    sort_order,
    is_active,
    is_system,
    path,
    path_array,
    depth
   FROM account_tree
  ORDER BY path_array;


