    CONSTRAINT pay_rate_schedules_scope_shape CHECK ((((scope = 'employee'::text) AND (employee_id IS NOT NULL) AND (job_id IS NULL)) OR ((scope = 'job'::text) AND (job_id IS NOT NULL) AND (employee_id IS NULL)) OR ((scope = 'pay_code'::text) AND (job_id IS NULL) AND (employee_id IS NULL))))
);


