    amount_paid numeric NOT NULL,
    payment_method character varying NOT NULL,
    payment_reference character varying,
    internal_reference character varying,
    notes text,
    created_at timestamp without time zone DEFAULT now(),
    status character varying(20) DEFAULT 'active'::character varying,
    cancellation_date timestamp without time zone,
    cancellation_reason text,
    bank_account character varying(20) DEFAULT NULL::character varying,
    journal_entry_id integer,
    is_auto_collection boolean DEFAULT false NOT NULL,
    receipt_allocation_id integer,
    CONSTRAINT chk_payments_bank_account CHECK ((((bank_account)::text = ANY (ARRAY[('CASH'::character varying)::text, ('BANK_PBB'::character varying)::text, ('BANK_ABB'::character varying)::text])) OR (bank_account IS NULL))),
    CONSTRAINT payments_payment_method_check CHECK (((payment_method)::text = ANY (ARRAY[('cash'::character varying)::text, ('cheque'::character varying)::text, ('bank_transfer'::character varying)::text, ('online'::character varying)::text])))
);


