--

COMMENT ON COLUMN public.payments.bank_account IS 'Target account code: CASH, BANK_PBB, or BANK_ABB. For cash payments, stores CASH. For cheque/bank/online, stores selected bank.';


--
-- Name: COLUMN payments.journal_entry_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.journal_entry_id IS 'Links to auto-generated journal entry (DR Bank/Cash, CR Trade Receivables). NULL if no journal created yet.';


--
-- Name: COLUMN payments.is_auto_collection; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.is_auto_collection IS 'true = automatic CASH-bill collection row owned by the invoice (non-posting; no own journal). Explicit flag — never infer from notes.';


--
-- Name: COLUMN payments.receipt_allocation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payments.receipt_allocation_id IS 'Owning receipt allocation when this row is the projection of a receipt. Set => row is managed by the receipt lifecycle.';


--
-- Name: CONSTRAINT chk_payments_bank_account ON payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT chk_payments_bank_account ON public.payments IS 'Ensures bank_account is one of the valid account codes';


