    external_reference character varying(255),
    amount numeric(12,2) NOT NULL,
    applied_amount numeric(12,2) DEFAULT 0 NOT NULL,
    refunded_amount numeric(12,2) DEFAULT 0 NOT NULL,
    legacy_payment_id integer,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT receipt_alloc_account_needs_target CHECK ((((allocation_type)::text <> 'account'::text) OR (target_account IS NOT NULL))),
    CONSTRAINT receipt_alloc_excess_needs_customer CHECK ((((allocation_type)::text <> 'excess'::text) OR (customer_id IS NOT NULL))),
    CONSTRAINT receipt_alloc_excess_within_amount CHECK (((applied_amount + refunded_amount) <= amount)),
    CONSTRAINT receipt_alloc_invoice_required CHECK ((((allocation_type)::text <> 'invoice'::text) OR (invoice_id IS NOT NULL))),
    CONSTRAINT receipt_allocations_allocation_type_check CHECK (((allocation_type)::text = ANY ((ARRAY['invoice'::character varying, 'excess'::character varying, 'account'::character varying])::text[]))),
    CONSTRAINT receipt_allocations_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT receipt_allocations_applied_amount_check CHECK ((applied_amount >= (0)::numeric)),
    CONSTRAINT receipt_allocations_refunded_amount_check CHECK ((refunded_amount >= (0)::numeric))
);


