    journal_entry_id integer,
    notes text,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    created_by character varying(255),
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_by character varying(255),
    cancellation_date timestamp without time zone,
    cancellation_reason text,
    cancelled_by character varying(255),
    CONSTRAINT receipts_origin_check CHECK (((origin)::text = ANY ((ARRAY['erp'::character varying, 'import_opening'::character varying])::text[]))),
    CONSTRAINT receipts_payment_method_check CHECK (((payment_method)::text = ANY ((ARRAY['cash'::character varying, 'cheque'::character varying, 'bank_transfer'::character varying, 'online'::character varying])::text[]))),
    CONSTRAINT receipts_pending_has_no_journal CHECK ((((status)::text <> 'pending'::text) OR (journal_entry_id IS NULL))),
    CONSTRAINT receipts_posted_needs_journal CHECK ((((status)::text <> 'posted'::text) OR (journal_entry_id IS NOT NULL) OR ((origin)::text = 'import_opening'::text))),
    CONSTRAINT receipts_posted_needs_posting_date CHECK ((((status)::text <> 'posted'::text) OR (posting_date IS NOT NULL) OR ((origin)::text = 'import_opening'::text))),
    CONSTRAINT receipts_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'posted'::character varying, 'cancelled'::character varying])::text[]))),
    CONSTRAINT receipts_total_amount_check CHECK ((total_amount > (0)::numeric))
);


