--
-- Name: staffs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.staffs (
    id character varying(255) NOT NULL,
    name character varying(255) NOT NULL,
    telephone_no character varying(255),
    email character varying(255),
    gender character varying(50),
    nationality character varying(255),
    birthdate date,
    address text,
    job jsonb,
    location jsonb,
    date_joined date,
    ic_no character varying(255),
    bank_account_number character varying(255),
    epf_no character varying(255),
    income_tax_no character varying(255),
    socso_no character varying(255),
    document character varying(255),
    payment_type character varying(255),
    payment_preference character varying(255),
    race character varying(255),
    agama character varying(255),
    date_resigned date,
    password character varying(255),
    updated_at timestamp with time zone DEFAULT now(),
    marital_status character varying(20) DEFAULT 'Single'::character varying,
    spouse_employment_status character varying(20),
    number_of_children integer DEFAULT 0,
    kwsp_number character varying(20),
    department character varying(50),
    head_staff_id character varying,
    epf_age_override character varying(20),
    epf_nationality_override character varying(20),
    socso_age_override character varying(20),
    sip_age_override character varying(20),
    CONSTRAINT staffs_epf_age_override_check CHECK (((epf_age_override IS NULL) OR ((epf_age_override)::text = ANY (ARRAY[('under_60'::character varying)::text, ('over_60'::character varying)::text, ('none'::character varying)::text])))),
    CONSTRAINT staffs_epf_nationality_override_check CHECK (((epf_nationality_override IS NULL) OR ((epf_nationality_override)::text = ANY (ARRAY[('local'::character varying)::text, ('foreign'::character varying)::text])))),
    CONSTRAINT staffs_id_no_whitespace CHECK (((id)::text !~ '[[:space:]]'::text)),
    CONSTRAINT staffs_marital_status_check CHECK (((marital_status)::text = ANY (ARRAY[('Single'::character varying)::text, ('Married'::character varying)::text]))),
    CONSTRAINT staffs_number_of_children_check CHECK ((number_of_children >= 0)),
    CONSTRAINT staffs_sip_age_override_check CHECK (((sip_age_override IS NULL) OR ((sip_age_override)::text = ANY (ARRAY[('under_60'::character varying)::text, ('over_60'::character varying)::text, ('none'::character varying)::text])))),
    CONSTRAINT staffs_socso_age_override_check CHECK (((socso_age_override IS NULL) OR ((socso_age_override)::text = ANY (ARRAY[('under_60'::character varying)::text, ('over_60'::character varying)::text, ('none'::character varying)::text])))),
    CONSTRAINT staffs_spouse_employment_status_check CHECK (((spouse_employment_status)::text = ANY (ARRAY[('Employed'::character varying)::text, ('Unemployed'::character varying)::text, (NULL::character varying)::text])))
);


